// Kuhn poker + vanilla CFR + exact best response, in the browser.
//
// This is a faithful port of the project's Python reference
// (poker_alpha/games/kuhn.py + poker_alpha/solvers/cfr.py +
// solvers/evaluation.py): deterministic full-tree traversal,
// simultaneous regret updates, regret matching with uniform fallback.
// It is validated in vitest against a committed fixture generated by the
// Python implementation (same iterations -> same average strategy within
// floating-point tolerance) — see kuhn.test.ts.
//
// Cards: 0=J, 1=Q, 2=K. Actions: "p" (pass/check/fold) and "b" (bet/call).

export const CARDS = [0, 1, 2] as const;
export const CARD_NAMES = ["J", "Q", "K"];
export const ACTIONS = ["p", "b"] as const;
export type KuhnAction = (typeof ACTIONS)[number];

const TERMINAL = new Set(["pp", "bp", "bb", "pbp", "pbb"]);

export interface KuhnState {
  cards: [number, number] | null;
  history: string;
}

export function isTerminal(h: string): boolean {
  return TERMINAL.has(h);
}

export function currentPlayer(h: string): 0 | 1 {
  return (h.length % 2) as 0 | 1;
}

export function utility(cards: [number, number], h: string): number {
  const p0wins = cards[0] > cards[1];
  if (h === "bp") return 1;
  if (h === "pbp") return -1;
  if (h === "pp") return p0wins ? 1 : -1;
  if (h === "bb" || h === "pbb") return p0wins ? 2 : -2;
  throw new Error(`utility on non-terminal ${h}`);
}

export function infosetKey(cards: [number, number], h: string): string {
  return `${cards[currentPlayer(h)]}${h}`;
}

export const ALL_DEALS: [number, number][] = [];
for (const i of CARDS) for (const j of CARDS) if (i !== j) ALL_DEALS.push([i, j]);

export const INFOSET_KEYS: string[] = [];
for (const c of CARDS) for (const h of ["", "p", "b", "pb"]) INFOSET_KEYS.push(`${c}${h}`);

export type Strategy = Record<string, Record<string, number>>;

// ---------------------------------------------------------------------------
// vanilla CFR
// ---------------------------------------------------------------------------

export class KuhnCFR {
  regretSum: Record<string, [number, number]> = {};
  strategySum: Record<string, [number, number]> = {};
  iterations = 0;

  private node(key: string): void {
    if (!(key in this.regretSum)) {
      this.regretSum[key] = [0, 0];
      this.strategySum[key] = [0, 0];
    }
  }

  private matching(key: string): [number, number] {
    const r = this.regretSum[key];
    const pos: [number, number] = [Math.max(r[0], 0), Math.max(r[1], 0)];
    const total = pos[0] + pos[1];
    if (total > 0) return [pos[0] / total, pos[1] / total];
    return [0.5, 0.5];
  }

  currentStrategy(key: string): [number, number] {
    this.node(key);
    return this.matching(key);
  }

  averageStrategy(): Strategy {
    const out: Strategy = {};
    for (const key of Object.keys(this.strategySum)) {
      const s = this.strategySum[key];
      const total = s[0] + s[1];
      out[key] =
        total > 0
          ? { p: s[0] / total, b: s[1] / total }
          : { p: 0.5, b: 0.5 };
    }
    return out;
  }

  private cfr(cards: [number, number], h: string, reach0: number, reach1: number, reachC: number): number {
    if (isTerminal(h)) return utility(cards, h);
    const player = currentPlayer(h);
    const key = infosetKey(cards, h);
    this.node(key);
    const strat = this.matching(key);
    const childValues: [number, number] = [0, 0];
    for (let i = 0; i < 2; i++) {
      const nh = h + ACTIONS[i];
      childValues[i] =
        player === 0
          ? this.cfr(cards, nh, reach0 * strat[i], reach1, reachC)
          : this.cfr(cards, nh, reach0, reach1 * strat[i], reachC);
    }
    const nodeValue = strat[0] * childValues[0] + strat[1] * childValues[1];
    const sign = player === 0 ? 1 : -1;
    const ownReach = player === 0 ? reach0 : reach1;
    const cfReach = (player === 0 ? reach1 : reach0) * reachC;
    const rs = this.regretSum[key];
    const ss = this.strategySum[key];
    for (let i = 0; i < 2; i++) {
      rs[i] += cfReach * sign * (childValues[i] - nodeValue);
      ss[i] += ownReach * strat[i];
    }
    return nodeValue;
  }

  iterate(): number {
    let value = 0;
    const prob = 1 / ALL_DEALS.length;
    for (const deal of ALL_DEALS) {
      value += prob * this.cfr(deal, "", 1, 1, prob);
    }
    this.iterations += 1;
    return value;
  }

  train(n: number): void {
    for (let i = 0; i < n; i++) this.iterate();
  }

  reset(): void {
    this.regretSum = {};
    this.strategySum = {};
    this.iterations = 0;
  }
}

// ---------------------------------------------------------------------------
// exact evaluation: expected value + best response + exploitability
// ---------------------------------------------------------------------------

function probsAt(strategy: Strategy, key: string): [number, number] {
  const s = strategy[key];
  if (!s) return [0.5, 0.5];
  const p = Math.max(s.p ?? 0, 0);
  const b = Math.max(s.b ?? 0, 0);
  const t = p + b;
  return t > 0 ? [p / t, b / t] : [0.5, 0.5];
}

export function gameValue(strategy: Strategy): number {
  const walk = (cards: [number, number], h: string): number => {
    if (isTerminal(h)) return utility(cards, h);
    const probs = probsAt(strategy, infosetKey(cards, h));
    return probs[0] * walk(cards, h + "p") + probs[1] * walk(cards, h + "b");
  };
  let v = 0;
  for (const deal of ALL_DEALS) v += walk(deal, "") / ALL_DEALS.length;
  return v;
}

/** Exact imperfect-information best response of `brPlayer` against
 * `strategy`, honoring information sets (max over actions of the
 * reach-weighted sum across states in the set). Returns the BR value to
 * brPlayer and the pure BR policy. */
export function bestResponse(
  strategy: Strategy,
  brPlayer: 0 | 1,
): { value: number; policy: Record<string, KuhnAction> } {
  // enumerate (cards, history) with opponent+chance reach
  type Entry = { cards: [number, number]; h: string; reach: number };
  const byInfoset = new Map<string, Entry[]>();
  const collect = (cards: [number, number], h: string, reach: number): void => {
    if (isTerminal(h)) return;
    const player = currentPlayer(h);
    if (player === brPlayer) {
      const key = infosetKey(cards, h);
      if (!byInfoset.has(key)) byInfoset.set(key, []);
      byInfoset.get(key)!.push({ cards, h, reach });
      for (const a of ACTIONS) collect(cards, h + a, reach);
    } else {
      const probs = probsAt(strategy, infosetKey(cards, h));
      for (let i = 0; i < 2; i++) collect(cards, h + ACTIONS[i], reach * probs[i]);
    }
  };
  for (const deal of ALL_DEALS) collect(deal, "", 1 / ALL_DEALS.length);

  const memo = new Map<string, number>();
  const policy: Record<string, KuhnAction> = {};
  const value = (cards: [number, number], h: string): number => {
    // value to brPlayer with opponent fixed, assuming br plays `policy`
    if (isTerminal(h)) {
      const u = utility(cards, h);
      return brPlayer === 0 ? u : -u;
    }
    const player = currentPlayer(h);
    if (player === brPlayer) {
      const a = policy[infosetKey(cards, h)];
      return value(cards, h + a);
    }
    const probs = probsAt(strategy, infosetKey(cards, h));
    return probs[0] * value(cards, h + "p") + probs[1] * value(cards, h + "b");
  };
  // resolve infosets deepest-first so child decisions are already fixed
  const keys = [...byInfoset.keys()].sort((a, b) => b.length - a.length);
  for (const key of keys) {
    const entries = byInfoset.get(key)!;
    let best: KuhnAction = "p";
    let bestVal = -Infinity;
    for (const a of ACTIONS) {
      policy[key] = a;
      let v = 0;
      for (const e of entries) v += e.reach * value(e.cards, e.h + a);
      if (v > bestVal + 1e-12) {
        bestVal = v;
        best = a;
      }
    }
    policy[key] = best;
    memo.set(key, bestVal);
  }
  let total = 0;
  const rootValue = (cards: [number, number], h: string): number => value(cards, h);
  for (const deal of ALL_DEALS) total += rootValue(deal, "") / ALL_DEALS.length;
  return { value: total, policy };
}

/** Exploitability: average of both best-response gains over the game
 * value (chips/hand). 0 at an exact equilibrium. */
export function exploitability(strategy: Strategy): number {
  const v = gameValue(strategy);
  const br0 = bestResponse(strategy, 0).value;
  const br1 = bestResponse(strategy, 1).value;
  return (br0 - v + (br1 - -v)) / 2;
}

/** Sample an action from a mixed strategy with the provided uniform
 * random number (deterministic given u). */
export function sampleAction(strategy: Strategy, key: string, u: number): KuhnAction {
  const [p] = probsAt(strategy, key);
  return u < p ? "p" : "b";
}
